package org.zhixiaoce.aperture;
public final class GalleryUploadEpochTest {
    static int n;static void ok(boolean v,String label){if(!v)throw new AssertionError(label);n++;}
    public static void main(String[] args){
        GalleryUploadEpoch g=new GalleryUploadEpoch();Object web=new Object(),nativePage=new Object();g.page(web);ok(g.accept(web)==null,"background cannot accept");g.active(true);GalleryUploadEpoch.Permit first=g.accept(web);ok(first!=null&&g.valid(first),"fresh active owner accepted");ok(g.claim(first),"queued request can enter once");ok(!g.claim(first),"duplicate worker cannot start twice");g.active(false);ok(!g.valid(first),"pause revokes current request");g.active(true);ok(!g.valid(first)&&!g.claim(first),"resume never revives old request");GalleryUploadEpoch.Permit second=g.accept(web);ok(second!=null&&g.valid(second),"new explicit confirmation after resume allowed");g.page(nativePage);ok(!g.valid(second),"fallback invalidates old owner before UI delivery");ok(g.accept(web)==null,"old owner cannot accept on native page");GalleryUploadEpoch.Permit third=g.accept(nativePage);ok(third!=null&&g.valid(third),"fresh native owner confirmation allowed");g.revoke();ok(!g.claim(third),"close before queued start prevents claim");GalleryUploadEpoch.Permit fourth=g.accept(nativePage);g.end();ok(!g.valid(fourth)&&!g.claim(fourth),"finish request immediately blocks queued start and UI");g.active(true);g.page(web);ok(g.accept(web)==null,"ended instance cannot revive after resume or page replacement");g.end();ok(!g.valid(first),"repeated end remains revoked");
        GalleryUploadEpoch h=new GalleryUploadEpoch();h.page(web);h.active(true);GalleryUploadEpoch.Permit inFlight=h.accept(web);ok(h.claim(inFlight),"in-flight work entered while authorized");h.end();ok(!h.valid(inFlight),"end rejects result from already-entered work");
        System.out.println("GalleryUploadEpoch: "+n+" model checks passed; no listener or Android Activity");
    }
}
